# owner: platform
import unittest
from hourglass.timesheet import weekly_rows
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError

def make(worker, day, start, end):
    return Shift(worker, day, Span(start, end))

class WeeklyRowsTests(unittest.TestCase):
    def test_busiest_first(self):
        rows = weekly_rows([
            make("Ana", "mon", 540, 600),
            make("Bob", "mon", 540, 780),
            make("Bob", "tue", 540, 570)
        ])
        self.assertEqual(rows, [
            "Bob: 2 shifts, 4.5 hours",
            "Ana: 1 shifts, 1.0 hours"
        ])

    def test_empty_raises(self):
        with self.assertRaises(ProjectError):
            weekly_rows([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ProjectError):
            weekly_rows([make("  ", "mon", 540, 600)])
